import{at as e,it as t,n,vt as r}from"./chunks/framework.BWMsmqky.js";var i=JSON.parse(`{"title":"CDN URL anatomy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/url-anatomy.md","filePath":"guide/url-anatomy.md"}`),a={name:`guide/url-anatomy.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="cdn-url-anatomy" tabindex="-1">CDN URL anatomy <a class="header-anchor" href="#cdn-url-anatomy" aria-label="Permalink to “CDN URL anatomy”">​</a></h1><p>Every Uploadcare CDN URL follows one structure. Once you know it, the parser&#39;s output (and the rest of this library) is obvious.</p><h2 id="a-file-url" tabindex="-1">A file URL <a class="header-anchor" href="#a-file-url" aria-label="Permalink to “A file URL”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://1s4oyld5dc.ucarecd.net/c2499162-…-47e858/-/crop/640x480/-/preview/400x400/photo.jpg</span></span>
<span class="line"><span>└──────┬───────────┘└─────┬───────────┘└──────────┬──────────────────┘└───┬────┘</span></span>
<span class="line"><span>     cdnBase              uuid                operations               filename</span></span></code></pre></div><ul><li>cdnBase: scheme + host, no path</li><li>uuid: the file id</li><li>operations: zero or more <code>-/name/params/</code> directives, applied in order as a pipeline</li><li>filename: optional, anything after the last operation without a trailing slash</li></ul><p>One directive is an <strong>operation</strong> (<code>resize/300x</code>); the whole serialized run of them is the <strong>modifiers</strong> (<code>-/resize/300x/-/blur/10/</code>), which is the word Uploadcare&#39;s API uses for a file&#39;s stored transformation string (<code>cdnUrlModifiers</code>). This library parses modifiers into operations and serializes them back — see <a href="/uploadcare-js-api-clients/cdn-url/guide/string-level-api.html">the string-level API</a> for working with the string form directly.</p><p><code>parseCdnUrl</code> returns exactly these fields, discriminated by <code>kind</code>:</p><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> parsed</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> parseCdnUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url)</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// parsed.kind: &#39;file&#39; | &#39;group&#39; | &#39;group-element&#39; | &#39;archive&#39; | &#39;proxy&#39;</span></span></code></pre></div><p>The shape only has the fields its kind allows, and TypeScript narrows on <code>kind</code>:</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>Fields</th></tr></thead><tbody><tr><td><code>file</code></td><td><code>uuid</code>, <code>conversion</code>, <code>operations</code>, <code>filename</code>, <code>search</code>, <code>hash</code></td></tr><tr><td><code>group</code></td><td><code>group: { uuid, count }</code>, no operations, by CDN design</td></tr><tr><td><code>group-element</code></td><td><code>group</code>, <code>nth</code>, <code>operations</code>, <code>filename</code>, <code>search</code>, <code>hash</code></td></tr><tr><td><code>archive</code></td><td><code>group</code>, <code>archive</code> (the format), <code>filename</code>, no operations</td></tr><tr><td><code>proxy</code></td><td><code>sourceUrl</code>, <code>operations</code>; the source keeps its own query/hash</td></tr></tbody></table><p>All kinds carry <code>cdnBase</code>.</p><h2 id="domains" tabindex="-1">Domains <a class="header-anchor" href="#domains" aria-label="Permalink to “Domains”">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Host</th><th>Notes</th></tr></thead><tbody><tr><td><code>legacy</code></td><td><code>ucarecdn.com</code></td><td>the original shared domain</td></tr><tr><td><code>prefixed</code></td><td><code>&lt;prefix&gt;.ucarecd.net</code></td><td>per-project subdomain, computed from your public key. Yes, <code>ucarecd.net</code> is a different zone than <code>ucarecdn.com</code>, not a typo</td></tr><tr><td><code>custom</code></td><td><code>cdn.example.com</code></td><td>your CNAME</td></tr><tr><td><code>proxy</code></td><td><code>&lt;pubkey&gt;.ucr.io</code></td><td>delivery proxy endpoints</td></tr></tbody></table><div class="language-ts" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { detectDomainKind } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@uploadcare/cdn-url&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">detectDomainKind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://1zlmtnsbgr.ucarecd.net&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// → &#39;prefixed&#39;</span></span></code></pre></div><p>The parser and serializer work identically on all of them. The cdnBase is just a field, which makes <a href="/uploadcare-js-api-clients/cdn-url/how-to/render-stored-urls.html#rebasing-onto-another-domain">rebasing between domains</a> a one-liner. For choosing the base you <em>build</em> with — and deriving the prefixed one from your public key — see <a href="/uploadcare-js-api-clients/cdn-url/guide/cdn-base.html">The CDN base</a>.</p><h2 id="group-urls" tabindex="-1">Group URLs <a class="header-anchor" href="#group-urls" aria-label="Permalink to “Group URLs”">​</a></h2><p>A group id is a uuid with a file count: <code>:uuid~3</code>. Group roots list the files and cannot carry operations; individual files are addressed with <code>nth</code> (zero-based) and can:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://1s4oyld5dc.ucarecd.net/:uuid~3/                          group root</span></span>
<span class="line"><span>https://1s4oyld5dc.ucarecd.net/:uuid~3/nth/1/-/resize/256x/      second file, resized</span></span>
<span class="line"><span>https://1s4oyld5dc.ucarecd.net/:uuid~3/archive/zip/all.zip       originals as an archive</span></span></code></pre></div><p>See <a href="/uploadcare-js-api-clients/cdn-url/how-to/groups-and-archives.html">Groups &amp; archives</a>.</p><h2 id="proxy-urls" tabindex="-1">Proxy URLs <a class="header-anchor" href="#proxy-urls" aria-label="Permalink to “Proxy URLs”">​</a></h2><p>The delivery proxy fetches remote sources through the CDN. Operations sit between the endpoint and the embedded source URL, which keeps its own query string:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://pubkey.ucr.io/-/preview/-/resize/500x/https://example.com/image.jpg?v=2</span></span>
<span class="line"><span>└────────┬──────────┘└──────────┬───────────┘└──────────────┬─────────────────┘</span></span>
<span class="line"><span>       cdnBase              operations                    sourceUrl</span></span></code></pre></div><p>See <a href="/uploadcare-js-api-clients/cdn-url/how-to/remote-images-via-proxy.html">Remote images via proxy</a>.</p><h2 id="conversion-paths" tabindex="-1">Conversion paths <a class="header-anchor" href="#conversion-paths" aria-label="Permalink to “Conversion paths”">​</a></h2><p>Two different beasts, easy to confuse:</p><ul><li><code>gif2video</code> is a URL, an on-the-fly CDN operation: <code>https://…/:uuid/gif2video/-/format/webm/</code>. Note there&#39;s no <code>-/</code> between the uuid and the prefix.</li><li><code>video</code> and <code>document</code> are paths, not URLs: <code>/:uuid/video/-/size/720x540/</code> strings you submit to the REST convert API. The library builds them with <code>videoPath</code> / <code>documentPath</code> and deliberately returns no domain.</li></ul><p>The parser still understands <code>/:uuid/video/…</code> inside a full URL, because finished conversion jobs are addressable on the CDN that way.</p><h2 id="query-strings-and-fragments" tabindex="-1">Query strings and fragments <a class="header-anchor" href="#query-strings-and-fragments" aria-label="Permalink to “Query strings and fragments”">​</a></h2><p><code>?token=…</code> (secure delivery signatures) and <code>#fragments</code> are preserved verbatim through parse → serialize. The library never generates tokens. Remember that editing operations invalidates an existing signature, since it was computed over the old path.</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};